const cmds=[
  "rg -n --glob '*.lean' 'FinSubext|namespace DatG0' AlgebraicJacobian",
  "rg -n --glob '*.lean' 'theorem exists_subalgebra_fg|exists_subalgebra_fg' .lake/packages/mathlib/Mathlib",
  "rg -n --glob '*.lean' 'def toIntermediateField|toIntermediateField' .lake/packages/mathlib/Mathlib",
  "rg -n --glob '*.lean' 'fg_iff_finiteType|finite_of_essFiniteType_of_isAlgebraic' .lake/packages/mathlib/Mathlib",
  "sed -n '1,180p' lakefile.toml"
];
